 {
  recorder.CancelCapture();if(saving)return;if(!consent.Checked){Tell(new(false,UiText.T("请先了解并同意启用助手。")));consent.Focus();return;}
  if(ShortcutChanged&&recorder.Entry.Value.Length>0&&!confirmed.Checked){Tell(new(false,UiText.T("请先确认快捷键与微信一致；也可点“稍后设置”，只保存其他选项。")));confirmed.Focus();return;}
