  try{var r=await host.Save(new(enabled.Checked,startup.Checked,selectedPath,recorder.Entry.Value,confirmed.Checked,pauseShortcut.Checked,ShortcutChanged));if(IsDisposed)return;if(r.Success)ReadValues();Tell(r);}
  catch(Exception ex){Tell(new(false,CenterCopy.FriendlyFailure(ex)));}
  finally{saving=false;if(!IsDisposed){nav.Enabled=true;foreach(var p in pages)p.Enabled=true;UpdateDraft();RefreshStatus();}}
 }
